#include "stdlib/math/base/special/round10f.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/math/base/special/roundf.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/number/float32/base/to_float32.h"
#include <stdint.h>

/**
* Rounds a single-precision floating-point number to the nearest multiple
* of `10^n` using round-to-nearest-even.
*
* @param x  input value
* @param n  integer power of 10 indicating the decimal place
* @return   rounded value
*/
float stdlib_base_round10f( const float x, const int32_t n ) {
	float s;
	float y;

	/* Propagate NaN and ±infinity: */
	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_infinitef( x ) ) {
		return x;
	}

	/* Preserve sign of ±0.0: */
	if ( x == 0.0f ) {
		return x;
	}

	/* Scale by 10^(-n): */
	s = stdlib_base_powf( 10.0f, (float)(-n) );
	y = stdlib_base_to_float32( x * s );

	/* Round (ties-to-even): */
	y = stdlib_base_roundf( y );

	/* Scale back: */
	y = stdlib_base_to_float32( y / s );

	return y;
}
